import { Tabs } from '@base-ui/react/tabs';
import { ArrowRight, ChevronLeft, ChevronRight, Lightbulb, Trash2 } from 'lucide-react';
import { useMemo, useState } from 'react';
import { useScripts } from '@/context/ScriptsContext';
import { lex } from '@/lib/lex';
import { PRESETS } from '@/presets';
import { TUTORIAL_STEPS } from '@/tutorial';
import { GUIDE } from '@/guide';
import { cn } from '@/lib/utils';
import Highlighted from '../editor/Highlighted';

function CodeBlock({ code }: { code: string }) {
  const tokens = useMemo(() => lex(code), [code]);
  return (
    <pre className="mt-3 overflow-x-auto rounded-lg border border-border/70 bg-editor px-3 py-2.5 font-mono text-[12.5px] leading-[1.65] [tab-size:3]">
      <Highlighted source={code.replace(/\n$/, '')} tokens={tokens} />
    </pre>
  );
}

function timeAgo(t: number) {
  const s = Math.round((Date.now() - t) / 1000);
  if (s < 60) return 'just now';
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  return new Date(t).toLocaleDateString();
}

function ListButton({
  title,
  detail,
  active,
  onClick,
  trailing,
}: {
  title: string;
  detail: string;
  active?: boolean;
  onClick: () => void;
  trailing?: React.ReactNode;
}) {
  return (
    <li className="group relative">
      <button
        type="button"
        onClick={onClick}
        aria-current={active || undefined}
        className={cn(
          'w-full rounded-lg px-3 py-2.5 text-left transition-colors',
          active ? 'bg-sand/18' : 'hover:bg-muted',
        )}
      >
        <span className="block text-sm font-semibold">{title}</span>
        <span className="mt-0.5 block text-[13px] leading-snug text-muted-foreground">{detail}</span>
      </button>
      {trailing}
    </li>
  );
}

function ExamplesPanel() {
  const { scripts, open, remove, activeId, name } = useScripts();
  const starters = PRESETS.filter((p) => p.level === 'starter');
  const advanced = PRESETS.filter((p) => p.level === 'advanced');
  return (
    <div className="space-y-6">
      <section>
        <h3 className="panel-heading">Start from an example</h3>
        <ul className="space-y-0.5">
          {starters.map((p) => (
            <ListButton
              key={p.id}
              title={p.name}
              detail={p.description}
              active={activeId === null && name === p.name}
              onClick={() => open(p.name, p.source)}
            />
          ))}
        </ul>
      </section>
      <section>
        <h3 className="panel-heading">My scripts</h3>
        {scripts.length === 0 ? (
          <p className="rounded-lg border border-dashed border-border px-3 py-3 text-[13px] text-muted-foreground">
            Nothing saved yet. Give your world a name at the top, then press Save. It stays in this browser.
          </p>
        ) : (
          <ul className="space-y-0.5">
            {scripts.map((s) => (
              <ListButton
                key={s.id}
                title={s.name}
                detail={`Saved ${timeAgo(s.updatedAt)}`}
                active={s.id === activeId}
                onClick={() => open(s.name, s.source, s.id)}
                trailing={
                  <button
                    type="button"
                    onClick={() => remove(s.id)}
                    className="absolute top-2 right-2 rounded-md p-1.5 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100 hover:bg-destructive/10 hover:text-destructive focus-visible:opacity-100"
                    title={`Delete ${s.name}`}
                  >
                    <Trash2 className="size-3.5" />
                    <span className="sr-only">Delete {s.name}</span>
                  </button>
                }
              />
            ))}
          </ul>
        )}
      </section>
      <section>
        <h3 className="panel-heading">Big projects from the original team</h3>
        <ul className="space-y-0.5">
          {advanced.map((p) => (
            <ListButton
              key={p.id}
              title={p.name}
              detail={p.description}
              active={activeId === null && name === p.name}
              onClick={() => open(p.name, p.source)}
            />
          ))}
        </ul>
      </section>
    </div>
  );
}

function LearnPanel() {
  const { open } = useScripts();
  const [index, setIndex] = useState(0);
  const step = TUTORIAL_STEPS[index];
  return (
    <div>
      <ol className="mb-5 flex gap-1" aria-label="Tutorial steps">
        {TUTORIAL_STEPS.map((s, i) => (
          <li key={s.id} className="flex-1">
            <button
              type="button"
              onClick={() => setIndex(i)}
              aria-current={i === index ? 'step' : undefined}
              title={s.title}
              className={cn(
                'block h-1.5 w-full rounded-full transition-colors',
                i < index ? 'bg-sand' : i === index ? 'bg-foreground' : 'bg-border',
              )}
            >
              <span className="sr-only">
                Step {i + 1}: {s.title}
              </span>
            </button>
          </li>
        ))}
      </ol>
      <p className="text-[13px] font-medium text-muted-foreground">
        Step {index + 1} of {TUTORIAL_STEPS.length}
      </p>
      <h3 className="mt-1 text-xl font-bold tracking-[-0.02em] text-balance">{step.title}</h3>
      <p className="mt-1.5 text-[15px] font-medium">{step.goal}</p>
      <div className="mt-3 space-y-2 text-sm leading-relaxed text-foreground/85">
        {step.explain.map((line) => (
          <p key={line}>{line}</p>
        ))}
      </div>
      <CodeBlock code={step.newCode} />
      <button
        type="button"
        onClick={() => open(`Tutorial: ${step.title}`, step.source)}
        className="btn-run mt-3 inline-flex h-9 w-full items-center justify-center gap-2 rounded-lg text-sm font-semibold"
      >
        Load this step and run it <ArrowRight className="size-4" />
      </button>
      <div className="mt-4 flex gap-2.5 rounded-lg bg-sand/14 px-3 py-2.5 text-sm leading-relaxed">
        <Lightbulb className="mt-0.5 size-4 shrink-0 text-sand-strong" />
        <p>
          <span className="font-semibold">Try it: </span>
          {step.tryIt}
        </p>
      </div>
      <div className="mt-5 flex justify-between">
        <button
          type="button"
          className="btn-quiet h-8 px-2.5"
          disabled={index === 0}
          onClick={() => setIndex(index - 1)}
        >
          <ChevronLeft className="size-4" /> Back
        </button>
        <button
          type="button"
          className="btn-quiet h-8 px-2.5"
          disabled={index === TUTORIAL_STEPS.length - 1}
          onClick={() => setIndex(index + 1)}
        >
          Next step <ChevronRight className="size-4" />
        </button>
      </div>
    </div>
  );
}

function GuidePanel() {
  return (
    <div className="space-y-7">
      <p className="text-sm leading-relaxed text-foreground/85">
        Sandscript reads almost like English. Here is every piece of the language, with a tiny example for each.
      </p>
      {GUIDE.map((section) => (
        <section key={section.id} id={`guide-${section.id}`}>
          <h3 className="text-[15px] font-bold tracking-[-0.01em]">{section.title}</h3>
          <div className="mt-1.5 space-y-1.5 text-sm leading-relaxed text-foreground/85">
            {section.body.map((line) => (
              <p key={line}>{line}</p>
            ))}
          </div>
          {section.code && <CodeBlock code={section.code} />}
          {section.entries && (
            <dl className="mt-3 divide-y divide-border/70 rounded-lg border border-border/70">
              {section.entries.map((entry) => (
                <div key={entry.name} className="px-3 py-2">
                  <dt className="font-mono text-[12.5px] font-semibold text-syntax-declaration">{entry.name}</dt>
                  <dd className="mt-0.5 text-[13px] leading-snug text-foreground/80">{entry.does}</dd>
                </div>
              ))}
            </dl>
          )}
        </section>
      ))}
    </div>
  );
}

const TABS = [
  { value: 'examples', label: 'Examples' },
  { value: 'learn', label: 'Learn' },
  { value: 'guide', label: 'Guide' },
] as const;

export default function Sidebar() {
  return (
    <Tabs.Root defaultValue="examples" className="flex min-h-0 flex-col border-r border-border/70 bg-sidebar">
      <Tabs.List className="relative flex h-12 shrink-0 items-end gap-5 border-b border-border/70 px-5">
        {TABS.map((tab) => (
          <Tabs.Tab
            key={tab.value}
            value={tab.value}
            className="h-full text-sm font-semibold text-muted-foreground transition-colors outline-none hover:text-foreground focus-visible:text-foreground data-[selected]:text-foreground"
          >
            {tab.label}
          </Tabs.Tab>
        ))}
        <Tabs.Indicator className="absolute bottom-[-1px] left-[var(--active-tab-left)] h-0.5 w-[var(--active-tab-width)] rounded-full bg-foreground transition-all duration-200 ease-out" />
      </Tabs.List>
      {TABS.map((tab) => (
        <Tabs.Panel key={tab.value} value={tab.value} className="min-h-0 flex-1 overflow-y-auto px-4 py-5 outline-none">
          {tab.value === 'examples' && <ExamplesPanel />}
          {tab.value === 'learn' && <LearnPanel />}
          {tab.value === 'guide' && <GuidePanel />}
        </Tabs.Panel>
      ))}
    </Tabs.Root>
  );
}
